def eligible_pairs(
    parents: list[MergeCandidate], generation: int
) -> list[tuple[MergeCandidate, MergeCandidate]]:
    all_pairs = [
        (parents[first_index], parents[second_index])
        for first_index in range(len(parents))
        for second_index in range(first_index + 1, len(parents))
    ]
    if generation != 0:
        return all_pairs
    filtered = [pair for pair in all_pairs if not shares_too_many_steps(pair[0], pair[1])]
    return filtered if filtered else all_pairs


def build_generation(
    parents: list[MergeCandidate], generation: int, evaluate: Evaluator
) -> list[MergeCandidate]:
    children: list[MergeCandidate] = []
    for first, second in eligible_pairs(parents, generation):
        for t in SLERP_T_SWEEP:
            children.append(merge_pair(first, second, t, generation, evaluate))
    return children
